/**
 * The charts that compute their own rows.
 *
 * Most charts read a catalog. These three do arithmetic — comparing Golden Bot against Death Wave
 * uptime, ranking Golden Tower income, pricing the UW+ upgrade tiers — so each owns a builder
 * rather than a table.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    src/charts/datasets/gold-bot-vs-death-wave, src/charts/datasets/golden-tower, src/charts/datasets/types, src/charts/datasets/uw-plus
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
export * from './types'
export * from './gold-bot-vs-death-wave'
export * from './golden-tower'
export * from './uw-plus'
